style.css:
/* Pinterest azul aesthetic para Stylish */

/* Botón Guardar */
button[aria-label*="Guardar"],
button[data-test-id="PinBetterSaveButton"] {
    background: #4f8cff !important;
    color: white !important;
    border-radius: 24px !important;
    transition: 0.2s ease !important;
}

/* Hover del botón */
button[aria-label*="Guardar"]:hover,
button[data-test-id="PinBetterSaveButton"]:hover {
    background: #3b7cff !important;
}

/* Botones principales */
div[data-test-id="header-profile"] a,
a[href*="/settings/"],
a[href*="/following/"] {
    background: #4f8cff !important;
    color: white !important;
    border-radius: 20px !important;
    padding: 8px 14px !important;
}

/* Foto de perfil borde azul */
img {
    border-color: #4f8cff !important;
}

/* Links y detalles azules */
a {
    color: #4f8cff !important;
}

/* Mantener fondo blanco */
body,
html {
    background: white !important;
}
